const fs = require('fs');

const enhancements = {

'6-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Copilot Chat Quick Commands Drill', content: 'This 8-minute drill tests GitHub Copilot Chat\'s most useful inline commands.\n\n**Step 1 — Open VS Code** with GitHub Copilot installed and active.\n\n**Step 2 — Open or create a Python or JavaScript file** with 20-30 lines of code (ask Copilot to generate a sample if needed).\n\n**Step 3 — Test these Copilot Chat slash commands** on the code:\n- Select a function → Copilot Chat → `/explain` — does it accurately describe what the function does?\n- Select a function → `/doc` — does it generate a useful docstring?\n- Select a function → `/tests` — does it generate sensible test cases?\n- Introduce a bug manually → `/fix` — does Copilot catch and fix it?\n\n**Step 4 — Rate each command:** Which is most useful for your work? Which produced the weakest output?\n\n**Step 5 — Test inline chat:** Click anywhere in the code, press Ctrl+I, and ask "Add error handling to this function." How good is the result?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Real Code Review with Copilot Chat', content: 'Use Copilot Chat to perform a structured review of real code — code you wrote or AI generated.\n\n**Step 1 — Open a real file** from a project you\'re working on. Pick something meaningful — not a toy example.\n\n**Step 2 — Run a structured review** using Copilot Chat (or Claude if you don\'t have Copilot):\n```\nReview this code as a senior engineer. Check for:\n1. Logic errors or edge cases that aren\'t handled\n2. Performance issues\n3. Security vulnerabilities\n4. Missing error handling\n5. Code that could be simplified without losing clarity\n\nFor each issue found: state the line, what\'s wrong, and the specific fix.\n```\n\n**Step 3 — Fix at least 3 issues** the review identifies.\n\n**Step 4 — Mandatory adversarial review:** Ask again: *"You just reviewed this code and found issues. Now find 3 MORE problems you didn\'t mention in your first pass. Be specific."*\n\n**Step 5 — Commit the improved code** with a message describing what the review found and fixed.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Refactor a Real Function', content: 'Use Copilot Chat\'s refactoring to improve real code while keeping it working.\n\n**Step 1 — Find a function in your code** that is:\n- Longer than 20 lines, OR\n- Has nested if statements 3+ levels deep, OR\n- Has duplicate code in multiple places\n\n**Step 2 — Ask Copilot Chat to refactor it:**\n```\nRefactor this function to be more readable and maintainable. Specifically:\n- Extract any duplicated logic into helper functions\n- Simplify nested conditionals where possible\n- Reduce the function length if it\'s doing too many things\n\nDo not change the external behaviour — the function should produce the same outputs for the same inputs.\n```\n\n**Step 3 — Compare the before and after.** Is the refactored version actually more readable? Did it change any behaviour?\n\n**Step 4 — Run your tests** (or manually verify) that the refactored version produces the same results as the original.\n\n**Step 5 — Ask Claude:** *"Review both versions of this function [paste both]. Was the refactoring an improvement? What trade-offs did it make?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build an AI-Assisted Debugging Workflow', content: 'Create a repeatable debugging process that uses AI as the first-response tool for any error.\n\n**Step 1 — Identify a real bug** in your code — or deliberately introduce one to practice.\n\n**Step 2 — Follow this debugging workflow:**\n\n**Step A — Read the error message completely.** Copy the full error including the stack trace.\n\n**Step B — Form a hypothesis:** Before asking AI, write one sentence: "I think the bug is caused by [your guess]."\n\n**Step C — Ask Copilot Chat:**\n```\nI got this error: [paste full error and stack trace]\nCode context: [paste the relevant code]\nMy hypothesis: [your guess]\n\nIs my hypothesis correct? If not, what is the actual cause? Give me the specific fix.\n```\n\n**Step D — Apply the fix.** Run the code again.\n\n**Step E — Write a test** that would have caught this bug before it reached you.\n\n**Step 3 — Mandatory review:** Ask: *"Now that this bug is fixed, are there other places in the codebase where the same pattern might cause the same bug?"*' },

    { type: 'quiz', question: 'You use Copilot Chat\'s /fix command on a bug. It suggests a fix that looks reasonable. What should you do before accepting it?', options: ['Accept it — Copilot\'s fixes are tested and safe', 'Read the fix carefully to understand what changed and why, then test it to verify it fixes the bug without introducing new ones', 'Run it only in a test environment first', 'Ask Copilot to explain the fix in detail before accepting'], correct: 1, explanation: 'Always understand a fix before applying it. Copilot\'s /fix suggestions are plausible but not guaranteed correct — they can fix the visible symptom while missing the root cause, or introduce subtle new bugs. Read what changed, understand why, and test the fix. This also builds your understanding of the bug so you don\'t make the same mistake again.' },

    { type: 'quiz', question: 'Copilot Chat\'s /tests command generates unit tests for your function. What is the most important check before using these tests?', options: ['That the tests pass', 'That the tests actually test meaningful behaviour, not just that the function runs without error', 'That there are at least 10 tests', 'That the test file follows your team\'s naming conventions'], correct: 1, explanation: 'AI-generated tests often pass trivially without testing anything meaningful — for example, just checking that the function returns something, not that it returns the right thing for edge cases. The most important check is: do these tests actually verify behaviour that matters? Add tests for edge cases (empty input, null values, maximum values, invalid types) that AI often misses.' }
  ]
},

'6-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Continue.dev Setup with Claude', content: 'Continue.dev is an open-source AI assistant that lets you use Claude (or any model) in VS Code. This drill sets it up.\n\n**Step 1 — Install Continue** from the VS Code Extensions marketplace.\n\n**Step 2 — Configure Claude as your model:** Click the Continue icon in the Activity Bar → Settings → Add Model → Anthropic → Claude Sonnet 4.x. Enter your API key.\n\n**Step 3 — Test the chat:** Open Continue sidebar (Ctrl+Shift+I or click its icon). Ask: "Explain what VS Code extensions do."\n\n**Step 4 — Test code-aware chat:** Open a code file. Select some code. Right-click → Continue → "Ask about selection". Does Continue include your selected code in the context?\n\n**Step 5 — Compare Continue to Copilot Chat** if you have both: Ask the same code question in both. Which gives a more useful response for your code?\n\n**Step 6 — Ask Claude:** *"I\'m using Continue.dev with Claude. What are the 5 most effective ways to use it that are different from just asking questions in a browser tab?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI Code Chat on a Real Problem', content: 'Use Continue.dev (or any VS Code AI assistant) to solve a real coding problem — from question to working code.\n\n**Step 1 — Identify a real coding task** you need to complete: a function to write, a problem to solve, a feature to add.\n\n**Step 2 — Open the Continue sidebar** alongside your code file.\n\n**Step 3 — Have a conversation** to build the solution:\n- Start with your goal: "I need to build a function that does [X]"\n- Ask for an approach: "What\'s the best approach for this?"\n- Ask for the code: "Write the implementation"\n- Ask for explanation: "Explain the key parts I might not understand"\n\n**Step 4 — Insert the code** into your file.\n\n**Step 5 — Mandatory review:** Tell Continue: *"Review the code you just wrote. What are 3 potential problems: edge cases not handled, performance issues, or error scenarios? Fix each one."*\n\n**Step 6 — Run and test** the code. If it fails, paste the error back into Continue.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Model Comparison in Continue.dev', content: 'Continue.dev lets you use multiple AI models. This workshop compares them on a coding task.\n\n**Step 1 — In Continue.dev settings**, add at least two models: Claude Sonnet (for quality) and a free model like Llama via Ollama (if set up) or Gemini.\n\n**Step 2 — Choose a real coding task** — something where quality matters.\n\n**Step 3 — Ask the same question in each model** using Continue\'s model selector. Record:\n- Quality of explanation\n- Correctness of code\n- How well it handles your specific context\n\n**Step 4 — Identify the best model** for this type of task. Note: for professional work, Claude Sonnet is typically best for code quality. Smaller models are faster but less capable.\n\n**Step 5 — Ask Claude:** *"When working with AI coding assistants in VS Code, what types of tasks should I use a high-quality large model (like Claude Sonnet) vs when is a smaller, faster model acceptable?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Custom Continue.dev Prompt Library', content: 'Continue.dev supports custom slash commands — create a library of specialised coding prompts.\n\n**Step 1 — Identify your 5 most common coding tasks** where you ask AI for help.\n\n**Step 2 — In Continue.dev config** (open config.json from Continue settings), add custom slash commands:\n```json\n"slashCommands": [\n  {\n    "name": "review",\n    "description": "Code review with security focus",\n    "prompt": "Review this code. Check for: (1) logic errors, (2) security vulnerabilities especially injection risks, (3) unhandled exceptions, (4) performance issues. For each issue found: state the line number, what\'s wrong, and the specific fix."\n  },\n  {\n    "name": "test",\n    "description": "Generate comprehensive tests",\n    "prompt": "Generate unit tests for this code. Include: happy path, edge cases (empty input, null values, max values), and error cases. Use the same test framework as any existing tests in the project."\n  }\n]\n```\n\n**Step 3 — Test each custom command** on real code.\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review my Continue.dev custom prompts. What\'s missing from each prompt that would make the AI output more reliable and actionable?"*' },

    { type: 'quiz', question: 'What is the main advantage of Continue.dev over GitHub Copilot for Claude users?', options: ['Continue.dev has better code completion', 'Continue.dev is open-source and lets you use Claude as your AI model, while Copilot only uses GitHub\'s OpenAI-based models', 'Continue.dev is faster', 'Continue.dev works without an internet connection'], correct: 1, explanation: 'The key advantage: Continue.dev is model-agnostic — you can configure it to use Claude, GPT-4, Gemini, or local models. GitHub Copilot is locked to GitHub\'s model selection (OpenAI-based). For developers who prefer Claude\'s reasoning and writing quality for code, Continue.dev is the path to having Claude as your primary in-editor AI assistant.' },

    { type: 'quiz', question: 'You use Continue.dev and notice it doesn\'t seem to understand the structure of your project — it gives generic answers that ignore your actual codebase. What should you do?', options: ['Switch to GitHub Copilot', 'Use Continue\'s @codebase or @file context features to explicitly reference relevant files in your questions', 'Accept that AI can\'t understand project context', 'Ask very specific questions and provide all context manually in each message'], correct: 1, explanation: 'Continue.dev supports context providers that give the AI visibility into your codebase. Using @codebase (searches your project), @file (references a specific file), or @folder (references a directory) explicitly brings relevant code into the conversation context. Without context references, the AI only sees what you paste — with them, it can reason about your actual project structure.' }
  ]
},

'6-5': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Debug a Real Error with AI', content: 'This drill practices the complete AI-assisted debugging cycle on a real error.\n\n**Step 1 — Find or create a bug.** Either find a real bug in your code, or create one: take a working 20-line Python script and deliberately introduce a bug (wrong variable name, off-by-one error, missing return statement).\n\n**Step 2 — Run the code** and copy the complete error message and stack trace.\n\n**Step 3 — Before asking AI** — read the error message yourself and form a hypothesis. Write: "I think the error is at line X because Y."\n\n**Step 4 — Paste to Claude.ai or your VS Code AI:**\n```\nI have this error:\n[paste full error and stack trace]\n\nHere is the relevant code:\n[paste the function/class where the error occurs]\n\nMy hypothesis: [your guess]\n\nIs my hypothesis right? What is the actual cause? Give me the specific line to fix and the fix.\n```\n\n**Step 5 — Apply the fix.** Run again.\n\n**Step 6 — Write a note:** What type of error was this? How would you recognise the same pattern next time?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Use VS Code Debugger with AI Guidance', content: 'The VS Code debugger (breakpoints, step-through) is more powerful than print statements. This workshop uses AI to guide you through it.\n\n**Step 1 — Ask Claude:** *"I want to use the VS Code debugger for Python. Explain: (1) what a breakpoint is and how to set one, (2) what step over vs step into means, (3) how to inspect variable values during debugging, (4) when the debugger is more useful than print statements."*\n\n**Step 2 — Set a breakpoint** in your code: click in the gutter (left of line numbers) to set a red circle.\n\n**Step 3 — Start debugging:** Press F5 (Run and Debug). The program pauses at your breakpoint.\n\n**Step 4 — Inspect variables** in the Variables panel (left side). Hover over variables to see their current values.\n\n**Step 5 — Step through:** Press F10 (Step Over) to advance one line at a time. Watch variables change.\n\n**Step 6 — Ask Claude to help you interpret what you see:** *"The debugger shows variable X has value Y at this line. I expected Z. What does this tell me about where the bug is?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Debugging Patterns and Anti-patterns', content: 'Learn the debugging patterns that separate skilled developers from beginners — and how AI accelerates each.\n\n**Step 1 — Ask Claude:** *"Describe the 5 most common debugging strategies used by experienced developers. For each, explain: when to use it, the basic steps, and how AI assistance improves it."*\n\n**Step 2 — Read about these strategies:**\n- Binary search debugging (bisect the problem)\n- Rubber duck debugging (explain to AI)\n- Reproduce minimum (find the smallest code that causes the bug)\n- Check assumptions (are your variables actually what you think they are?)\n- Read the error message (the full message, not just the last line)\n\n**Step 3 — Apply one strategy** to a real bug you\'re working on.\n\n**Step 4 — Ask Claude:** *"I\'m using [strategy] to debug [describe your bug]. Here\'s what I\'ve found so far: [describe]. What should I check next?"*\n\n**Step 5 — Write a 3-sentence debugging checklist** you\'ll use for the next bug you encounter.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Write a Bug Report with AI Help', content: 'If you work in a team, writing a clear bug report is essential. AI can help you write better bug reports faster.\n\n**Step 1 — Find a real bug** in your code or use a hypothetical one.\n\n**Step 2 — Ask Claude to help structure the bug report:**\n```\nI found a bug and need to write a clear bug report. Here are my notes:\n[describe what happened, what you did, what you expected, what occurred instead]\n\nWrite a structured bug report with:\n- Summary (one sentence)\n- Environment (OS, language version, relevant package versions)\n- Steps to reproduce (numbered, specific)\n- Expected behaviour\n- Actual behaviour\n- Error output\n- Possible cause (if known)\n- Severity assessment\n```\n\n**Step 3 — Review the bug report.** Is it complete? Could someone else reproduce it from these steps alone?\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review this bug report. What information is missing that would make it harder to diagnose and fix? What would a senior developer want to know that isn\'t here?"*\n\n**Step 5 — Save this bug report template** in your prompt library.' },

    { type: 'quiz', question: 'Your Python script crashes with an IndexError. The error points to line 43. Before asking AI for help, what should you do?', options: ['Ask AI immediately — it will diagnose faster than you can', 'Look at line 43, identify the list or array being indexed, and check what value the index variable has at the time of the crash', 'Add print statements at every line before 43', 'Restart Python and try again'], correct: 1, explanation: 'IndexError means you\'re trying to access an index that doesn\'t exist in a list. Before asking AI, read the error: what variable is being accessed, and what is its value? Often a quick look at line 43 reveals the issue — you\'re using index 10 on a list with only 5 elements. This understanding makes your AI question much more specific: "I have a list of 5 items and I\'m accessing index X because [reason] — how do I fix the boundary condition?"' },

    { type: 'quiz', question: 'What is the main advantage of using the VS Code debugger\'s breakpoints over adding print() statements to debug code?', options: ['Breakpoints are faster to set than typing print statements', 'Breakpoints pause execution and let you inspect ALL variables at once without modifying the code — you can explore state interactively', 'Breakpoints only work for Python', 'Breakpoints automatically fix the bug'], correct: 1, explanation: 'Breakpoints let you pause execution and inspect the full program state — all variables, the call stack, the values in memory — without modifying your source code. Print statements only show what you anticipated you\'d need to see, require code modification, and leave debugging artifacts if you forget to remove them. For complex bugs, the debugger reveals unexpected state that you never would have thought to print.' }
  ]
},

'6-6': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Cursor First Session', content: 'Cursor is a VS Code fork with AI built into the editor at a deeper level. This drill explores its key differentiators.\n\n**Step 1 — Download and open Cursor** (cursor.sh). It imports all your VS Code extensions and settings automatically.\n\n**Step 2 — Test Cursor\'s AI chat:** Press Ctrl+L to open the AI chat sidebar. Ask about your current project.\n\n**Step 3 — Test Cmd+K (or Ctrl+K) inline editing:** Click inside a function, press Ctrl+K, and type "add input validation" — Cursor generates the code inline without switching to a sidebar.\n\n**Step 4 — Test Apply from chat:** In the chat, ask Cursor to refactor a function. Notice it shows a diff and you can Accept or Reject.\n\n**Step 5 — Test Cursor\'s codebase understanding:** Ask "Where is [function name] defined?" or "What does this project do?" — Cursor indexes your entire codebase.\n\n**Step 6 — Compare to Copilot Chat:** What can Cursor do that Copilot Chat cannot, or does better?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build a Feature with Cursor\'s AI', content: 'Use Cursor\'s deeper AI integration to build a complete feature — from specification to working code.\n\n**Step 1 — Open a real project** in Cursor.\n\n**Step 2 — Describe the feature** you want to add in Cursor\'s chat (Ctrl+L):\n```\nI want to add [feature description] to this project. The feature should:\n- [requirement 1]\n- [requirement 2]\n- [requirement 3]\n\nBefore writing any code: describe your implementation plan. What files will you modify? What new functions/classes will you create? What are the risks?\n```\n\n**Step 3 — Review the plan.** If you agree, say "implement it."\n\n**Step 4 — Watch Cursor write the changes.** It will show diffs for each file. Review each diff before accepting.\n\n**Step 5 — Mandatory review:** After accepting all changes, ask: *"Review the changes you just made. Find 3 potential problems: error cases not handled, edge cases missed, or interactions with existing code that might break."*\n\n**Step 6 — Run and test** the new feature.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Cursor vs VS Code + Copilot Comparison', content: 'Understand the real differences between Cursor and VS Code with Copilot — so you can make an informed choice.\n\n**Step 1 — Choose a real coding task** — ideally one that involves multiple files.\n\n**Step 2 — Complete the task in VS Code + Copilot Chat.** Note: how many steps it takes, how much context you have to provide, how the code quality looks.\n\n**Step 3 — Complete the same task in Cursor.** Note the same metrics.\n\n**Step 4 — Compare:**\n- Which required less manual context-providing?\n- Which understood your existing code better?\n- Which produced better first-attempt code?\n- Which was more transparent about what it was doing?\n\n**Step 5 — Ask Claude:** *"I compared VS Code+Copilot and Cursor on [your task]. Here are my observations: [describe]. Which should I use as my primary editor for [your work type] and why?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Cursor Composer for Multi-File Tasks', content: 'Cursor Composer (Ctrl+Shift+I or Ctrl+I in full) can make changes across multiple files simultaneously — a task that requires careful human oversight.\n\n**Step 1 — Open Composer** (Ctrl+Shift+I in Cursor).\n\n**Step 2 — Give it a multi-file task:**\n```\nI want to rename the function `calculate_total` to `compute_final_price` everywhere in this project. Make sure to update:\n- The function definition\n- All call sites\n- Any docstrings or comments that reference the function name\n- Any test files\n```\n\n**Step 3 — Review EVERY diff Composer shows** before accepting. This is critical — multi-file changes can break things if any individual change is wrong.\n\n**Step 4 — Run your tests** after accepting changes.\n\n**Step 5 — Mandatory safety check:** Ask Cursor: *"What could go wrong with the changes you just made? What tests should I run to verify nothing is broken?"*\n\n**Step 6 — Commit the changes** with a descriptive commit message.' },

    { type: 'quiz', question: 'Cursor\'s AI can read your entire codebase. What is the key responsibility this creates for you as the developer?', options: ['You must always accept Cursor\'s suggestions to get the full benefit', 'You must review every AI-generated change carefully — Cursor\'s codebase understanding makes it more capable but also more capable of making confident mistakes across many files', 'You should only use Cursor for small projects so the AI doesn\'t get confused', 'You must keep your codebase very small for Cursor to work effectively'], correct: 1, explanation: 'Codebase-aware AI is more powerful but not infallible — it can make plausible-sounding but wrong architectural decisions because it sees your full codebase. The more capable the AI, the more important careful review becomes. When Cursor makes a multi-file change, review every individual diff, run your tests, and don\'t accept bulk changes you haven\'t read.' },

    { type: 'quiz', question: 'What is Cursor\'s Ctrl+K (inline edit) most useful for compared to the chat sidebar?', options: ['Ctrl+K is more powerful for complex features', 'Ctrl+K is faster for small, targeted edits to existing code without leaving your current context — the chat is better for planning and larger features', 'Ctrl+K only works on Python files', 'Ctrl+K is the only way to make AI changes without review'], correct: 1, explanation: 'Ctrl+K is optimised for small, in-place edits: "add a parameter", "rename this variable", "add error handling here". It generates code directly in the editor without a conversation. The chat sidebar (Ctrl+L) is better for: understanding code, planning larger changes, multi-file operations, and when you want to discuss options before implementing. Using the right tool for the scope of the task is the key skill.' }
  ]
},

'6-7': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Windsurf First Session', content: 'Windsurf (from Codeium) is an AI-first editor with a "flow" approach to human-AI collaboration. This drill explores what makes it different.\n\n**Step 1 — Download and open Windsurf** (codeium.com/windsurf).\n\n**Step 2 — Open Cascade** (Windsurf\'s AI panel) — Ctrl+L or click the AI icon.\n\n**Step 3 — Open a real project.** Ask Cascade: "What does this project do?" — Windsurf\'s AI indexes your codebase.\n\n**Step 4 — Test Cascade\'s flow mode:** Ask it to add a feature. Notice how it: asks clarifying questions, shows its plan, makes changes, and explains each step.\n\n**Step 5 — Test the context window:** Ask about a specific function. Does Windsurf correctly reference your actual code?\n\n**Step 6 — Compare first impressions:** vs Cursor and VS Code — which feels most natural for your workflow?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Use Windsurf to Improve a Real Codebase', content: 'Use Windsurf\'s Cascade to make meaningful improvements to real code.\n\n**Step 1 — Open a real project** in Windsurf.\n\n**Step 2 — Ask Cascade to do a code health assessment:**\n```\nReview this codebase and identify the top 3 improvements I should make. For each improvement:\n- Describe the current problem\n- Show which files/functions are affected\n- Describe the proposed solution\n- Estimate the risk of making the change\n```\n\n**Step 3 — Choose the improvement** with the best risk/benefit ratio and ask Cascade to implement it.\n\n**Step 4 — Watch the implementation.** Review every file Cascade changes.\n\n**Step 5 — Mandatory review:** Ask Cascade: *"Review the changes you just made. What edge cases might be broken? What tests should I run? What did you not do that you considered doing?"*\n\n**Step 6 — Run tests and commit** if the implementation looks correct.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Windsurf vs Cursor Comparison', content: 'Both Windsurf and Cursor are AI-first editors. This workshop identifies which is better for your specific workflow.\n\n**Step 1 — Choose a medium-complexity coding task** — something that involves 2-3 files and requires understanding existing code.\n\n**Step 2 — Complete the task in Cursor.** Record:\n- Time taken\n- Number of exchanges\n- Quality of first output\n- How much context you had to explain\n\n**Step 3 — Complete the same task in Windsurf.** Record the same metrics.\n\n**Step 4 — Compare the user experience:**\n- Which felt more natural?\n- Which produced more accurate code?\n- Which was more transparent about what it was doing?\n- Which handled uncertainty better?\n\n**Step 5 — Ask Claude:** *"Based on these comparison notes [describe your findings], which editor would you recommend for someone who [describe your work profile]? What factors should matter most in the choice?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — AI Editor Decision Matrix', content: 'Build a personalised decision matrix to choose the right AI editor for different situations.\n\n**Step 1 — List your top 5 coding task types.** Be specific: "writing new Python functions from scratch", "reviewing AI-generated code", "debugging runtime errors", etc.\n\n**Step 2 — For each task**, rate these editors on a 1-5 scale based on your experience: VS Code + Copilot, Cursor, Windsurf.\n\n**Step 3 — Ask Claude:** *"Based on these ratings [paste your matrix], what does this suggest about my workflow preferences? Are there patterns I should pay attention to?"*\n\n**Step 4 — Add two more rows to your matrix:** "Cost" and "Learning curve" — estimate these for each editor.\n\n**Step 5 — Make a decision:** Which 1-2 editors will you use going forward, and for what?\n\n**Step 6 — Set a 30-day trial:** Commit to your chosen setup for 30 days before evaluating again.' },

    { type: 'quiz', question: 'Windsurf\'s Cascade AI makes changes to 4 files simultaneously. You review the changes and one file looks correct, two look plausible, and one looks suspicious. What should you do?', options: ['Accept all changes — the AI knows the codebase better than you do', 'Accept the correct one, review the plausible ones more carefully, and ask Cascade to explain the suspicious one before accepting or rejecting it', 'Reject all changes and start over', 'Accept all and run tests — tests will catch any errors'], correct: 1, explanation: 'Review each change on its own merits — don\'t accept all because some look right. For the suspicious change: ask the AI to explain its reasoning, compare it to the existing code it\'s changing, and consider whether the change makes sense in the context of the original request. "Looks plausible" is not enough for code you\'ll ship. The most dangerous AI changes are the confident ones that are subtly wrong.' },

    { type: 'quiz', question: 'You are choosing between Cursor and Windsurf for your daily development. Both are AI-first editors. What is the most important factor in choosing between them?', options: ['Which one has more GitHub stars', 'Which one\'s AI model is technically the strongest', 'Which one\'s workflow fits how you naturally think and work — the best editor is the one you use effectively', 'Which one has been around longer'], correct: 2, explanation: 'Technical capability matters but workflow fit matters more for daily productivity. If Cursor\'s model is marginally stronger but Windsurf\'s flow approach matches how you think, Windsurf will make you more productive. Try both on real tasks (not toy examples) and pay attention to which one feels less like fighting the tool. The best AI editor is the one you\'re actually using well, not the one with the best benchmark scores.' }
  ]
},

'6-8': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Personal AI Editor Assessment', content: 'Make a data-driven decision about your AI editor setup based on your actual experience.\n\n**Step 1 — List the editors you have tried** (even briefly): VS Code + Copilot, Continue.dev + Claude, Cursor, Windsurf, or others.\n\n**Step 2 — For each editor**, rate from 1-5 on:\n- Code quality produced\n- Understanding of my existing code\n- Speed (how fast it responds and implements)\n- Review experience (how easy to see and accept changes)\n- Setup effort\n- Cost\n\n**Step 3 — Ask Claude:** *"Based on these ratings [paste your matrix] and my work profile [describe: language, task types, team size], what AI editor setup would you recommend? Explain the reasoning."*\n\n**Step 4 — Identify your "must have" vs "nice to have" features.** What would make you switch editors?\n\n**Step 5 — Write a one-paragraph decision.** Your AI editor setup, why you chose it, and when you\'ll revisit the decision.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Hybrid AI Editor Setup', content: 'Many developers use more than one tool. This workshop designs a hybrid setup where each tool serves its best use case.\n\n**Step 1 — Identify your 4 most common AI coding tasks:**\n- Task type 1: [e.g., "write new functions from spec"]\n- Task type 2: [e.g., "review AI-generated code"]\n- Task type 3: [e.g., "debug runtime errors"]\n- Task type 4: [e.g., "refactor existing code"]\n\n**Step 2 — For each task**, decide: which AI tool would you use?\n\n**Step 3 — Ask Claude:** *"I want a hybrid AI editor setup using [your chosen tools]. For each of my task types [list them], which tool should I use and why? Identify any tasks where my tool choice might be wrong."*\n\n**Step 4 — Document your hybrid workflow** as a short reference:\n```\n## My AI Editor Workflow\n- New features: [tool + how]\n- Code review: [tool + how]\n- Debugging: [tool + how]\n- Refactoring: [tool + how]\n```\n\n**Step 5 — Commit to this workflow for 4 weeks.** After 4 weeks, review: which parts worked? What would you change?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Cost vs Quality Analysis', content: 'AI editor costs vary significantly. This workshop helps you maximise value for your specific situation.\n\n**Step 1 — Research current pricing** for each AI editor option:\n- GitHub Copilot Individual\n- Cursor Pro\n- Windsurf Pro\n- Claude API via Continue.dev (pay-per-use)\n- Free tiers of each\n\n**Step 2 — Estimate your monthly usage:** How many hours per week do you code? What percentage involves AI assistance?\n\n**Step 3 — Ask Claude:** *"Help me compare the cost-effectiveness of these AI editor options for a developer who codes [X] hours/week with [Y% AI assistance]: [list your options with their pricing]. What\'s the most cost-effective setup?"*\n\n**Step 4 — Factor in the value:** What is one hour of your time worth? If an AI editor saves you 30 minutes/day, how does that compare to its monthly cost?\n\n**Step 5 — Make a decision:** Is the cost of the tool you want justified? Write your conclusion.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build Your AI Coding Workflow Document', content: 'A documented workflow is the foundation of consistent, high-quality AI-assisted coding.\n\n**Step 1 — Ask Claude to help you write your workflow document:**\n```\nHelp me create an "AI Coding Workflow" document for my personal reference. I use [your tools] for [your work type].\n\nThe document should cover:\n1. How I start a new coding task (planning, speccing before coding)\n2. How I write code with AI assistance (tools, prompts, review process)\n3. How I review AI-generated code (checklist, mandatory steps)\n4. How I debug with AI help (process, what info to provide)\n5. How I commit and document (commit messages, code documentation)\n6. Red lines — things I never let AI do without full understanding\n```\n\n**Step 2 — Personalise every section** with your specific tools, prompts, and practices.\n\n**Step 3 — Add your review checklist** at the end: the mandatory steps before accepting any AI-generated code.\n\n**Step 4 — Mandatory meta-review:** Ask Claude: *"Review this workflow document. What important practices are missing? What common AI coding mistakes does this workflow not protect against?"*\n\n**Step 5 — Save and use:** This document is your operating manual for AI-assisted development.' },

    { type: 'quiz', question: 'You are comparing Cursor ($20/month) and using Claude API via Continue.dev (pay-per-use). What information do you need to make a cost-effective decision?', options: ['Just compare the monthly subscription costs', 'Estimate how many API calls you make per month to calculate Continue.dev costs, then compare to Cursor\'s flat rate considering both price and which produces better output for your work', 'Always choose the cheaper option', 'Always choose the more expensive option — it will be higher quality'], correct: 1, explanation: 'Cost-effectiveness requires knowing both the total cost of each option AND the value difference. Calculate: how many tokens you use per day × Claude API rates × days/month = monthly Continue.dev cost. Compare to Cursor\'s flat rate. If they\'re similar, quality and workflow fit become the deciding factor. Flat rates favor heavy users; pay-per-use favors occasional users. Neither is universally better.' },

    { type: 'quiz', question: 'A colleague says "I just use whichever AI coding tool is trending on social media." What is the problem with this approach?', options: ['Trending tools are usually poorly tested', 'Tool choice should be based on which tool produces the best output for your specific language, task type, and workflow — not popularity', 'Popular tools are always the most expensive', 'Trending tools change too frequently to learn properly'], correct: 1, explanation: 'The best AI coding tool for you depends on factors specific to your work: your programming language, your primary task types (building vs reviewing vs debugging), your team\'s tool chain, your budget, and how you naturally think about code. A tool that benchmarks well or trends on Twitter may be mediocre for your specific context. Use the data from your own experience — not others\' preferences.' }
  ]
},

'7-1': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Claude Code Orientation Drill', content: 'This 8-minute drill gives you a concrete picture of what Claude Code can do before you install it.\n\n**Step 1 — Ask Claude.ai:** *"Describe 5 concrete examples of tasks that Claude Code can complete that a VS Code developer using only Copilot Chat cannot. For each, describe what Claude Code does and why it\'s different."*\n\n**Step 2 — Read the examples.** Note which ones are most relevant to your work.\n\n**Step 3 — Ask Claude:** *"What is the main difference between Claude in the browser (claude.ai) and Claude Code in the terminal? When would I use each?"*\n\n**Step 4 — Ask Claude:** *"For a developer who builds [describe your project type], what would be the 3 most time-saving uses of Claude Code in a typical week?"*\n\n**Step 5 — Write down** the 3 use cases that would deliver the most value for your specific situation. Return to this list after you install Claude Code.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Understand the Agent Loop', content: 'Claude Code is an agent — it runs a loop of reasoning and tool use. Understanding this helps you work with it effectively.\n\n**Step 1 — Ask Claude.ai to explain the agent loop:**\n```\nExplain the Claude Code agent loop in plain English. Specifically:\n1. What happens when I give Claude Code a task?\n2. What "tools" does Claude Code have? (read files, run commands, etc.)\n3. How does Claude Code decide when the task is done?\n4. What can go wrong in the loop and how can I prevent it?\n5. When should I interrupt the loop vs let it run?\n```\n\n**Step 2 — Draw a simple diagram** (on paper) of the loop based on Claude\'s explanation.\n\n**Step 3 — Ask Claude:** *"Give me 3 examples of poorly-specified tasks that would cause Claude Code to go in the wrong direction, and the corrected version of each task that would lead to better results."*\n\n**Step 4 — Save the corrected task examples** as a reference for when you start using Claude Code.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Compare Claude Code to Other AI Coding Tools', content: 'Position Claude Code correctly in your toolset by understanding where it fits vs other tools.\n\n**Step 1 — Ask Claude:** *"Create a comparison of these AI coding tools for a developer who uses VS Code: GitHub Copilot, Cursor, Claude Code (CLI). For each, describe: best use cases, limitations, and which specific type of developer it\'s designed for."*\n\n**Step 2 — Map to your workflow:** For each tool in the comparison, identify: would I use this for Task Type A (your most common task)? Task Type B? Task Type C?\n\n**Step 3 — Ask Claude:** *"Given that I work on [your project type] in [your language], and my most common tasks are [list 3], which combination of these tools would make me most productive? Design a workflow that uses each tool for what it\'s best at."*\n\n**Step 4 — Note Claude Code\'s unique position:** It can run terminal commands, make changes across many files, write and run code, and work on long tasks autonomously. This is what separates it from in-editor AI.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Plan Your First Claude Code Projects', content: 'Before you use Claude Code, identify the best first tasks — ones where it will demonstrate its value clearly.\n\n**Step 1 — List 5-10 real tasks** from your work that would take you more than 30 minutes manually.\n\n**Step 2 — For each task**, answer:\n- Does it require reading/modifying multiple files? (Good for Claude Code)\n- Does it require running terminal commands? (Good for Claude Code)\n- Could it be described clearly in a single paragraph? (Required for Claude Code)\n- Could a wrong implementation cause serious problems? (Requires careful setup)\n\n**Step 3 — Rank your tasks** from best to worst fit for Claude Code.\n\n**Step 4 — Ask Claude:** *"I\'m planning my first Claude Code tasks. Here are my top 3 candidates: [describe them]. Rank them from easiest to hardest for an AI agent to complete correctly. For each, describe what setup I should do before running it."*\n\n**Step 5 — Save your ranked task list.** You\'ll use this in the next few lessons.' },

    { type: 'quiz', question: 'What is the fundamental difference between GitHub Copilot Chat and Claude Code?', options: ['Claude Code is smarter than Copilot Chat', 'Copilot Chat only answers questions and suggests code snippets; Claude Code is an autonomous agent that can read files, run commands, write code, and execute multi-step tasks', 'Claude Code only works with Python', 'Copilot Chat can run terminal commands but Claude Code cannot'], correct: 1, explanation: 'The key distinction is agentic capability. Copilot Chat and similar in-editor AIs respond to single requests — they suggest, and you act. Claude Code is an agent: it can take a complex task, break it into steps, read files to understand context, write code, run the code, see the output, fix errors, and continue — all autonomously. This enables it to complete tasks that would require multiple rounds of manual follow-through in a chat interface.' },

    { type: 'quiz', question: 'You ask Claude Code to "make this codebase better." Why is this a poor task specification?', options: ['Claude Code only works on single files', 'The task is too vague — Claude Code needs clear, specific objectives to work effectively and avoid making changes you didn\'t intend', 'Claude Code doesn\'t understand code quality', 'It would take too long'], correct: 1, explanation: '"Make this codebase better" is vague in every dimension — better how? Which files? What criteria? This forces Claude Code to make assumptions about what "better" means, which may not match your priorities. A good task is specific: "Add input validation to the user registration function in auth.py to handle empty strings and invalid email formats." The more specific the task, the more predictable and reviewable the result.' }
  ]
},

'7-2': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Install and Verify Claude Code', content: 'This drill gets Claude Code installed and running your first command.\n\n**Step 1 — Install Claude Code:**\n```powershell\nnpm install -g @anthropic-ai/claude-code\n```\n(Requires Node.js 18+. Run `node --version` first.)\n\n**Step 2 — Verify installation:**\n```powershell\nclaude --version\n```\n\n**Step 3 — Authenticate:**\n```powershell\nclaude\n```\nFollow the authentication flow (browser-based OAuth to your Claude account).\n\n**Step 4 — Run your first command in a project folder:**\n```powershell\ncd your-project-folder\nclaude\n```\nIn the Claude Code interface, type: "What files are in this project?"\n\n**Step 5 — Verify it can read your project:** Ask: "Summarise what this project does based on the files you can see."\n\n**Step 6 — Exit Claude Code:** Type /exit or press Ctrl+C.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — First Real Claude Code Task', content: 'Complete your first real Claude Code task — something genuinely useful.\n\n**Step 1 — Open Claude Code in a real project:**\n```powershell\ncd your-real-project\nclaude\n```\n\n**Step 2 — Give Claude Code a real, specific task** from your project (use your ranked list from Lesson 7-1 Workshop D). Keep it to something that should take under 10 minutes:\n- "Add a README.md to this project based on what you see in the files"\n- "Add docstrings to all functions in [filename]"\n- "Find any TODO comments in the codebase and list them"\n\n**Step 3 — Watch Claude Code work.** Notice: which tools does it use? Which files does it read? What commands does it run?\n\n**Step 4 — Review the output.** Is what Claude Code produced correct and useful?\n\n**Step 5 — Mandatory review:** In the Claude Code session, type: *"Review what you just did. What might be wrong or incomplete? What didn\'t you do that I might have expected?"*\n\n**Step 6 — Commit the result** with a descriptive message.' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Claude Code Permission Modes', content: 'Claude Code\'s permission system controls what it can do autonomously. Understanding it prevents surprises.\n\n**Step 1 — Read the permission documentation:**\n```powershell\nclaude --help\n```\nOr ask Claude.ai: "What are Claude Code\'s permission modes? What does each mode allow and prevent?"\n\n**Step 2 — Start Claude Code in conservative mode** (does not execute commands without approval):\n```powershell\nclaude --permission-mode=default\n```\n\n**Step 3 — Give it a task that requires running code.** Notice that it asks for permission before executing.\n\n**Step 4 — Compare:** Start a new session without permission restrictions. Give the same task. How does the behaviour differ?\n\n**Step 5 — Ask Claude:** *"For a developer working on a production codebase, what permission mode should they use for Claude Code? What are the risks of using fully autonomous mode?"*\n\n**Step 6 — Set your default:** Based on what you learned, what permission mode will you use by default?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Configure Claude Code for Your Environment', content: 'Configure Claude Code to work best in your specific development environment.\n\n**Step 1 — Check your Claude Code version and settings:**\n```powershell\nclaude --version\nclaude config\n```\n\n**Step 2 — Configure your model preference:**\n```powershell\nclaude config set model claude-sonnet-4-6\n```\n\n**Step 3 — Set up a CLAUDE.md** in your main project (we\'ll cover this in depth in Lesson 7-6, but start now):\n- Create `CLAUDE.md` in your project root\n- Add 3 basic things: what the project is, the main language/framework, and one thing Claude Code should always do (e.g., "Always run tests after making changes")\n\n**Step 4 — Test the configuration:** Start a Claude Code session and ask it to do a task. Does it follow your CLAUDE.md instruction?\n\n**Step 5 — Mandatory setup review:** Ask Claude: *"Review my Claude Code setup. What configuration or CLAUDE.md instructions should I add to make Claude Code more reliable for [your project type]?"*' },

    { type: 'quiz', question: 'You install Claude Code but the `claude` command is not found in your terminal. What is the most likely cause?', options: ['Claude Code requires a paid API subscription', 'npm did not add the global package location to your system PATH — you need to fix your PATH or use npx claude', 'Claude Code is only for Mac/Linux', 'You need to restart your computer'], correct: 1, explanation: 'When npm installs a global package (`npm install -g`), it places the executable in a global npm bin directory. If this directory isn\'t in your system PATH, the command won\'t be found. The fix on Windows: run `npm config get prefix` to find where npm installs globals, then add that path + \\node_modules\\.bin to your system PATH. Alternatively, use `npx @anthropic-ai/claude-code` to run without global installation.' },

    { type: 'quiz', question: 'Why is it important to create a CLAUDE.md file in your project before running Claude Code on it?', options: ['Claude Code won\'t work without a CLAUDE.md file', 'CLAUDE.md provides persistent project context — without it, Claude Code has to re-discover your project structure and conventions every session, leading to less consistent results', 'CLAUDE.md is required for authentication', 'CLAUDE.md sets the permission mode for the session'], correct: 1, explanation: 'CLAUDE.md is a persistent instruction file that Claude Code reads at the start of every session. It gives Claude Code: project purpose and architecture, conventions and style rules, what to avoid, commands to run for testing/building. Without it, you spend time re-establishing context each session and risk Claude Code making decisions that don\'t fit your project\'s conventions. It\'s project memory for the agent.' }
  ]
},

'7-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Project Reading Drill', content: 'Claude Code\'s most powerful first move is reading and understanding your entire project. This drill practices it.\n\n**Step 1 — Open Claude Code in a real project:**\n```powershell\ncd your-project\nclaude\n```\n\n**Step 2 — Ask Claude Code to understand the project** (these are different questions with different answers):\n- "What does this project do?"\n- "What are the main files and what does each one do?"\n- "What dependencies does this project have?"\n- "How would I run this project?"\n- "What tests exist, if any?"\n\n**Step 3 — Verify each answer.** Open the files mentioned. Is Claude Code\'s description accurate?\n\n**Step 4 — Ask a specific question** that requires reading code: "What happens when a user submits the login form?" or "What does the main() function do step by step?"\n\n**Step 5 — Ask about problems:** "What are potential issues or improvements you notice in this codebase?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Generate Project Documentation', content: 'Use Claude Code to generate real documentation for a project — one of its most immediately valuable uses.\n\n**Step 1 — Open Claude Code in a project** that lacks documentation.\n\n**Step 2 — Ask for comprehensive documentation:**\n```\nGenerate documentation for this project:\n1. A README.md with: project description, installation instructions, usage examples, configuration options\n2. Inline comments for any functions that lack them\n3. A CONTRIBUTING.md with: how to set up the development environment, code style guidelines, how to run tests, how to submit changes\n\nBase everything on what you actually see in the code — don\'t make up features that don\'t exist.\n```\n\n**Step 3 — Review all generated documentation.** Check every claim against the actual code.\n\n**Step 4 — Mandatory review:** In Claude Code: *"Review the documentation you just wrote. What did you assume or infer that might be wrong? What important information might you have missed?"*\n\n**Step 5 — Commit the documentation** with message "Add auto-generated documentation (reviewed)".' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Code Quality Assessment', content: 'Use Claude Code to assess the quality of a real codebase and produce an actionable improvement plan.\n\n**Step 1 — Open Claude Code in a project.**\n\n**Step 2 — Run a structured quality assessment:**\n```\nPerform a code quality assessment of this project. For each category, rate it Good/Fair/Poor and explain why:\n\n1. Code organisation: Are files and functions well-organised?\n2. Error handling: Are errors caught and handled appropriately?\n3. Documentation: Are functions and complex code documented?\n4. Test coverage: Are there tests? Do they cover important cases?\n5. Security: Any obvious security issues?\n6. Performance: Any obvious performance problems?\n7. Dependencies: Are dependencies up-to-date and minimal?\n\nEnd with: the top 3 improvements I should make first, in priority order.\n```\n\n**Step 3 — Review the assessment.** Do you agree? Are there categories where you know better than Claude Code?\n\n**Step 4 — Save the assessment** and plan to address the top priority this week.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Onboard Claude Code to a New Project', content: 'Create a reusable onboarding process for bringing Claude Code up to speed on any project.\n\n**Step 1 — Develop a standard "project onboarding" prompt** for Claude Code:\n```\nI\'m going to have you work on this project. Before we start:\n1. Read the README.md and CLAUDE.md (if they exist)\n2. List all the main source files and their purposes\n3. Identify the project\'s entry points\n4. Note any configuration files and what they control\n5. List the commands to: install dependencies, run the project, run tests\n6. Identify any patterns or conventions you notice in the code\n7. Tell me what you\'re unsure about — what would you need to know to work on this project effectively?\n```\n\n**Step 2 — Run this onboarding prompt** on a real project.\n\n**Step 3 — Answer Claude Code\'s questions.** Good questions mean it understood the project. Bad questions mean the documentation needs improvement.\n\n**Step 4 — Update CLAUDE.md** with the answers to questions Claude Code asked. This ensures the next session starts better.' },

    { type: 'quiz', question: 'Claude Code reads your project and says "I see this is a Flask web application." But it\'s actually a Django application. What should you do?', options: ['Trust Claude Code — it has better pattern recognition than you', 'Correct Claude Code immediately: "This is Django, not Flask" — never let it work with wrong assumptions', 'Restart the session and hope it gets it right this time', 'This doesn\'t matter — both frameworks work similarly'], correct: 1, explanation: 'Correct wrong assumptions immediately. If Claude Code believes the wrong framework, every subsequent piece of code it writes will use Flask patterns instead of Django patterns — potentially incorrect imports, wrong conventions, wrong CLI commands. In Claude Code, you can say "That\'s incorrect — this is a Django project, not Flask. Please re-read [key files] to confirm." Uncorrected wrong assumptions propagate through the entire session.' },

    { type: 'quiz', question: 'You ask Claude Code "what does this project do?" and it gives a long, detailed answer. What is the most important follow-up check?', options: ['Ask it to make the description shorter', 'Open the main source file and verify the description matches what the code actually does', 'Ask Claude Code to rate its own confidence', 'Share the description with a colleague to see if they agree'], correct: 1, explanation: 'Claude Code\'s project descriptions are based on what it reads in the code, documentation, and comments. If these are incomplete, misleading, or outdated, Claude Code\'s description will reflect those problems. Always verify by checking the actual code. A common failure mode: README.md describes what the project used to do, not what it currently does — and Claude Code describes the README, not reality.' }
  ]
},

'7-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — File Writing Drill', content: 'Practice asking Claude Code to write different types of files — the most fundamental Claude Code workflow.\n\n**Step 1 — Open Claude Code in a project:**\n```powershell\nclaude\n```\n\n**Step 2 — Ask Claude Code to write 3 different file types:**\n\nType 1 — Python utility:\n"Write a Python utility file called `utils.py` that contains: a function to validate email addresses, a function to format dates as YYYY-MM-DD, and a function to clean text (remove extra whitespace, strip HTML tags). Include docstrings and basic error handling."\n\nType 2 — Configuration file:\n"Write a `config.yaml` file for a web application with sections for: database settings, API keys (use placeholder values), logging level, and feature flags."\n\nType 3 — Test file:\n"Write a test file `test_utils.py` for the utils.py you just created. Include tests for valid and invalid inputs for each function."\n\n**Step 3 — Read each file.** Does each one do what you asked?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build a Complete Feature with Claude Code', content: 'Use Claude Code to implement a complete feature — from specification to working, tested code.\n\n**Step 1 — Write a feature specification** (1-2 paragraphs describing what you want to build and how it should work).\n\n**Step 2 — Start Claude Code and provide the specification:**\n```\nI want to implement the following feature: [your specification]\n\nBefore writing any code:\n1. Describe your implementation plan\n2. List the files you will create or modify\n3. Identify any risks or questions\n\nOnly start coding after I approve the plan.\n```\n\n**Step 3 — Review the plan.** Is the approach correct? Are there files it missed? Approve or redirect before implementation.\n\n**Step 4 — Let Claude Code implement.** Watch which files it creates/modifies.\n\n**Step 5 — Test the implementation:** "Run the tests for this feature. If they fail, fix them."\n\n**Step 6 — Mandatory code review:** "Review the code you just wrote. Find 3 potential issues a code reviewer would raise."' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Review and Compare AI-Written Files', content: 'Build the habit of careful file review after Claude Code writes or modifies code.\n\n**Step 1 — Ask Claude Code to write a function:**\n"Write a Python function that reads a CSV file, filters rows where a specified column value exceeds a threshold, and writes the filtered results to a new CSV file. Include error handling for file not found and invalid column names."\n\n**Step 2 — Read the generated file** character by character (at least the first 30 lines).\n\n**Step 3 — Answer these questions:**\n- Does it import everything it uses?\n- Does it handle the file-not-found case?\n- Does it handle the invalid column name case?\n- What happens if the CSV is empty?\n- What happens if the threshold is not a number?\n- Is the output file properly closed even if an error occurs?\n\n**Step 4 — Paste your findings back to Claude Code:** "I reviewed the code and found these issues: [list]. Fix each one."\n\n**Step 5 — Re-read the fixed version.** Did all issues get addressed?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Versioned File Writing with git', content: 'Pair Claude Code file writing with immediate git commits — creating a clear history of what AI wrote vs what you wrote.\n\n**Step 1 — Start with a clean git state:**\n```powershell\ngit status   # should show "nothing to commit"\n```\n\n**Step 2 — Ask Claude Code to write a file:**\n"Write a logging configuration module `logger.py` that sets up structured logging with different handlers for development (console) and production (file) environments."\n\n**Step 3 — Review the file** carefully.\n\n**Step 4 — Commit immediately:**\n```powershell\ngit add logger.py\ngit commit -m "Add logging module (AI-generated, reviewed 2026-06-11)"\n```\n\n**Step 5 — Make improvements** based on your review. Commit again:\n```powershell\ngit commit -m "Improve logging module: add rotation, fix missing handlers"\n```\n\n**Step 6 — This creates a clear history:** which code was AI-generated vs human-reviewed. This is professional practice for AI-assisted development.' },

    { type: 'quiz', question: 'Claude Code writes a 100-line Python file. You run it and it works correctly. Is this sufficient review?', options: ['Yes — if it runs without errors, the code is correct', 'No — a program can run without errors while having logic errors, security issues, or missing edge case handling', 'Yes — but only run it in production if the output looks right', 'It depends on how critical the code is'], correct: 1, explanation: 'Code that runs without errors can still be wrong in important ways: it might produce incorrect results for edge cases (empty input, unexpected formats), have security vulnerabilities (SQL injection, path traversal), have performance problems at scale, or miss error handling that would cause failures in production. "It ran" is a necessary but not sufficient condition for correct code. Always read AI-generated code.' },

    { type: 'quiz', question: 'What should you do when Claude Code says "I\'ll create a new file called database.py"?', options: ['Let it create the file and review it afterwards', 'Ask Claude Code to first show you the code it plans to write before creating the file, so you can review it before it\'s written', 'Accept all file creation requests automatically', 'Only allow Claude Code to modify existing files, never create new ones'], correct: 1, explanation: 'You can ask Claude Code to show you a plan or a draft before writing files. This is especially valuable for important files like database modules, authentication code, or anything touching production data. Say "Before creating the file, show me what you plan to write" or "Give me a summary of the file\'s design before implementing it." This puts you in the review loop before the code is written, not just after.' }
  ]
},

'7-5': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Accept/Reject Workflow Drill', content: 'Build fluency with the accept/reject workflow — your primary safety control over Claude Code.\n\n**Step 1 — Open Claude Code in a project:**\n```powershell\nclaude\n```\n\n**Step 2 — Ask for a change:** "Add a type annotation to every function in [filename]."\n\n**Step 3 — When Claude Code shows you the diff**, practice reviewing systematically:\n- Does every change look correct?\n- Did it miss any functions?\n- Did it add any unexpected changes?\n\n**Step 4 — Practice rejection:** If any change looks wrong, reject it and explain why: "Don\'t apply the change to the `__init__` function — it\'s a special method that doesn\'t need type annotations in this project\'s style."\n\n**Step 5 — Accept the rest** and verify the final state of the file.\n\n**Step 6 — Ask Claude:** "What is your general rule for when you will make a change without showing me the diff vs when you will show me?" — understand its default behaviour.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI-Assisted Code Review Session', content: 'Use Claude Code as a code reviewer — reviewing your own code or code from a colleague.\n\n**Step 1 — Identify code to review:** A pull request, a module you recently wrote, or code you\'re not confident about.\n\n**Step 2 — Ask Claude Code for a structured review:**\n```\nReview the code in [filename or directory]. I want:\n1. An overall assessment: is this code well-written?\n2. Specific issues found (with line numbers where applicable)\n3. Priority ranking: which issues should I fix first?\n4. Any patterns you notice across multiple issues\n\nBe critical — I\'m trying to improve the code, not feel good about it.\n```\n\n**Step 3 — For each issue Claude Code identifies**, decide: fix now, fix later, or disagree and explain why.\n\n**Step 4 — Ask Claude Code to fix the highest-priority issues:** "Fix items 1, 3, and 5 from your review."\n\n**Step 5 — Review each fix** before accepting. Did the fix address the issue without introducing new ones?\n\n**Step 6 — Commit with a review summary commit message.**' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Test Changes Before Accepting', content: 'The gold standard of Claude Code review: test the changes before accepting them.\n\n**Step 1 — Ask Claude Code to implement a small feature.** For example: "Add a caching layer to the `get_user_data` function so that it caches results for 60 seconds."\n\n**Step 2 — Review the diff** Claude Code shows.\n\n**Step 3 — Before accepting, ask Claude Code to test it:**\n"Before I accept these changes, run the existing tests to confirm they still pass. Also write and run a test specifically for the caching behaviour."\n\n**Step 4 — Watch Claude Code run tests.** If tests fail, it should fix the issues before you accept.\n\n**Step 5 — Only accept after tests pass.** This is the ideal workflow: AI writes → tests confirm → you accept.\n\n**Step 6 — Ask Claude Code:** "What edge cases in the caching behaviour are NOT covered by the tests you wrote?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build a Review Checklist for Claude Code Changes', content: 'Create a systematic checklist you run through every time Claude Code makes changes.\n\n**Step 1 — Ask Claude:** *"Create a code review checklist specifically for AI-generated code. What are the most common mistakes that AI makes when writing code that a human would catch? Organise by: logic errors, security issues, error handling gaps, and style/maintainability problems."*\n\n**Step 2 — Adapt the checklist** to your specific language and project type.\n\n**Step 3 — Apply the checklist** to a recent Claude Code change in your project. Did you find anything you would have missed without the checklist?\n\n**Step 4 — Mandatory meta-review:** Ask Claude: *"Review this checklist. What important items are missing that a security expert or senior engineer would add?"*\n\n**Step 5 — Save the checklist** and use it for every Claude Code review going forward.' },

    { type: 'quiz', question: 'Claude Code makes a change to 5 files. 4 look correct but 1 looks suspicious. What is the right course of action?', options: ['Accept all 5 — the AI package is usually correct', 'Accept the 4 correct ones and ask Claude Code to explain and redo the suspicious one', 'Reject all 5 and start over with a more specific task', 'Accept all 5 and run tests to catch any errors'], correct: 1, explanation: 'Accept what looks correct and address specific concerns individually. Rejecting all changes wastes the correct work; accepting suspicious changes passes your review responsibility to tests (which may not catch logic errors). Say: "I\'m accepting these 4 changes. For the change in [file], explain your reasoning and what it\'s supposed to accomplish — I want to verify before accepting it." This is precise, targeted review.' },

    { type: 'quiz', question: 'After accepting Claude Code\'s changes, you realise one of them introduced a bug. How do you recover?', options: ['Ask Claude Code to fix the bug in a new session', 'Use `git revert` to undo the commit, or `git checkout` to restore the specific file, then fix properly', 'Ask Claude Code to undo its previous changes', 'Manually fix the bug — this is too complex for git operations'], correct: 1, explanation: 'This is exactly what version control is for. If you committed Claude Code\'s changes: `git revert HEAD` creates a new commit that undoes the last one (safe for shared repos). If you haven\'t committed: `git checkout -- filename` restores the file to the last committed state. If the changes span multiple commits: `git rebase` or cherry-pick individual reverts. Always commit Claude Code\'s changes immediately after review so you have a clean revert point.' }
  ]
},

'7-6': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Write Your First CLAUDE.md', content: 'CLAUDE.md is the most important file in your AI coding workflow. This drill builds your first one.\n\n**Step 1 — Open Claude Code in a real project.**\n\n**Step 2 — Ask Claude Code to help you write CLAUDE.md:**\n```\nHelp me write a CLAUDE.md for this project. Read the project files and generate a CLAUDE.md that includes:\n1. Project purpose (1 paragraph)\n2. Architecture overview (key components and how they interact)\n3. Tech stack (languages, frameworks, major dependencies)\n4. Development commands (how to install, run, test)\n5. Code conventions I should follow\n6. Files/directories you should NOT modify without explicit instruction\n7. Common tasks and how to do them\n```\n\n**Step 3 — Review the generated CLAUDE.md.** What did Claude Code get right? What is wrong or missing?\n\n**Step 4 — Edit the CLAUDE.md** to correct errors and add your specific preferences and constraints.\n\n**Step 5 — Test it:** Start a new Claude Code session. Does Claude Code reference the CLAUDE.md in its initial understanding?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — CLAUDE.md for a New Project', content: 'Start a new project with CLAUDE.md written first — defining your conventions before any code is written.\n\n**Step 1 — Plan a small project** you\'re going to build. Write a 2-paragraph description of what it is and what it does.\n\n**Step 2 — Ask Claude.ai (in the browser, not Claude Code yet) to help design the project:**\n```\nI\'m building [describe your project]. Help me define:\n1. The tech stack (recommend the right tools for this type of project)\n2. The folder structure\n3. The key architectural decisions\n4. Code style conventions I should follow\n5. Testing strategy\n```\n\n**Step 3 — Create the project folder and a CLAUDE.md** based on the design decisions.\n\n**Step 4 — Then create the folder structure** and stub files (empty files with comments describing their purpose).\n\n**Step 5 — Open Claude Code in the project.** Ask: "Read CLAUDE.md and the project structure. Do you have any questions before we start building?" — this identifies gaps in your CLAUDE.md.\n\n**Step 6 — Update CLAUDE.md** with answers to Claude Code\'s questions.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — CLAUDE.md Best Practices Research', content: 'Research and apply CLAUDE.md best practices from the developer community.\n\n**Step 1 — Ask Claude:** *"What are the best practices for writing CLAUDE.md files? What have experienced Claude Code users found to be the most important things to include? What common mistakes should I avoid?"*\n\n**Step 2 — Review the best practices.** Which ones does your current CLAUDE.md follow? Which are you missing?\n\n**Step 3 — Look for patterns in the advice:**\n- What information does Claude Code need that it can\'t infer from code?\n- What constraints prevent Claude Code from making bad decisions?\n- What workflows should be documented?\n\n**Step 4 — Update your CLAUDE.md** with the best practices you were missing.\n\n**Step 5 — Mandatory review:** Ask Claude: *"Review this CLAUDE.md. What would cause Claude Code to misunderstand this project or make poor decisions even after reading this file?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — CLAUDE.md for Your Real Project', content: 'Produce a production-quality CLAUDE.md for a project you actively work on.\n\n**Step 1 — Open your most important project** in Claude Code.\n\n**Step 2 — Run the comprehensive CLAUDE.md generation:**\n```\nI need to create a comprehensive CLAUDE.md for this project. Please:\n1. Read all the key files (README, main source files, config files, tests)\n2. Generate a CLAUDE.md that would allow another AI agent to work on this project effectively with minimal additional guidance\n3. Include: project context, architecture, conventions, forbidden actions, testing requirements, and deployment considerations\n4. Be specific to what you actually see in the code — don\'t add generic advice\n```\n\n**Step 3 — Review every section** of the generated CLAUDE.md.\n\n**Step 4 — Add a "Never do this" section:** List specific things Claude Code should never do in your project (e.g., "Never modify the database schema directly — always use migrations").\n\n**Step 5 — Commit CLAUDE.md** to your repository so the whole team benefits.' },

    { type: 'quiz', question: 'You add the instruction "Always run tests before committing" to CLAUDE.md. What happens?', options: ['Claude Code will refuse to commit without running tests', 'Claude Code will read this instruction and follow it during sessions — running tests as part of its workflow before suggesting commits', 'CLAUDE.md is only read by humans, not by Claude Code', 'Claude Code will ask for permission to run tests each time'], correct: 1, explanation: 'Claude Code reads CLAUDE.md at the start of each session and uses its instructions to guide behaviour throughout. Instructions like "always run tests before committing" become part of its operating procedure for that project. It won\'t literally refuse to commit (it\'s not enforced programmatically), but it will include test-running as part of its process. Clear, specific instructions in CLAUDE.md are the primary way to shape Claude Code\'s default behaviour.' },

    { type: 'quiz', question: 'What is the most important thing to include in the "Never do this" section of a CLAUDE.md for a web application?', options: ['A list of all files that exist in the project', 'Instructions like "never modify authentication code without explicit instruction" or "never delete database migration files" — the high-risk operations that could cause serious damage if done autonomously', 'A reminder to write good commit messages', 'The project\'s git repository URL'], correct: 1, explanation: 'The "Never do this" section\'s value is preventing high-stakes mistakes. For a web app, dangerous autonomous actions include: modifying auth/security code, deleting migrations, changing API contracts that break clients, modifying production configuration. These are operations where an autonomous AI making a mistake could cause data loss, security vulnerabilities, or outages. Explicit prohibition is the strongest instruction you can put in CLAUDE.md.' }
  ]
},

'7-7': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — First Custom Slash Command', content: 'Build and test your first custom slash command — a reusable workflow trigger.\n\n**Step 1 — Check the slash commands directory:**\n```powershell\nmkdir -p .claude/commands\n```\n\n**Step 2 — Create a simple review command:**\n```powershell\nnew-item .claude/commands/review.md\n```\n\n**Step 3 — Add content to review.md:**\n```markdown\n# Code Review\n\nPerform a thorough code review of the specified files. For each file:\n1. Check for logic errors and edge cases not handled\n2. Identify security vulnerabilities\n3. Note missing error handling\n4. Flag performance concerns\n5. List specific line-numbered improvements\n\nEnd with: priority order for addressing the issues found.\n```\n\n**Step 4 — Test the command in Claude Code:**\n```\n/review [your filename]\n```\n\n**Step 5 — Evaluate the output.** Is it more thorough than your previous reviews? Adjust the command prompt until it\'s consistently useful.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build Your Custom Command Library', content: 'Create a library of custom commands for your most frequent Claude Code tasks.\n\n**Step 1 — Identify your top 5 Claude Code tasks** — things you ask Claude Code to do in almost every session.\n\n**Step 2 — For each task**, write a custom command file in `.claude/commands/`:\n\nExample commands to create:\n- `review.md` — structured code review (from Workshop A)\n- `document.md` — generate docstrings for all undocumented functions\n- `test.md` — generate tests for a module\n- `debug.md` — systematic debugging analysis\n- `refactor.md` — identify and execute safe refactoring\n\n**Step 3 — Include in each command:**\n- Clear objective\n- Specific steps or format you want\n- What to check or include\n- What NOT to do\n\n**Step 4 — Test each command** on real code in your project.\n\n**Step 5 — Mandatory review:** Ask Claude: *"Review these custom commands. For each, what important instruction is missing that would make the output more reliable and useful?"*' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Parameterised Commands', content: 'Make your custom commands more flexible with arguments.\n\n**Step 1 — Create a parameterised command** in `.claude/commands/analyse.md`:\n```markdown\n# Analyse Code\n\nAnalyse the code at $ARGUMENTS.\n\nProvide:\n1. What this code does (1 paragraph)\n2. How it interacts with the rest of the project\n3. The 3 most important things someone maintaining this code should know\n4. Anything that looks potentially fragile or confusing\n\nBe specific — reference actual function names and line numbers.\n```\n\n**Step 2 — Test with arguments:**\n```\n/analyse src/auth.py\n/analyse src/utils.py src/models.py\n```\n\n**Step 3 — Note how $ARGUMENTS is replaced** with what you type after the command.\n\n**Step 4 — Create a second parameterised command** for a task you do frequently.\n\n**Step 5 — Ask Claude:** *"What other techniques can I use in custom Claude Code commands to make them more powerful or flexible?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Share Commands Across a Team', content: 'Custom commands can be shared with your team so everyone benefits from your prompt engineering work.\n\n**Step 1 — Commit your .claude/commands/ directory** to your project repository:\n```powershell\ngit add .claude/commands/\ngit commit -m "Add custom Claude Code commands for team use"\n```\n\n**Step 2 — Add documentation** to your CLAUDE.md listing available commands and when to use each.\n\n**Step 3 — Ask Claude:** *"I want to share these custom Claude Code commands with my team. What should I include in the documentation so teammates can effectively use and contribute to the command library?"*\n\n**Step 4 — Write a brief guide** (add it to your CLAUDE.md or README) covering:\n- What custom commands exist\n- When to use each one\n- How to add new commands\n- How to report issues with a command\n\n**Step 5 — Test from a colleague\'s perspective:** Open the project in a fresh Claude Code session and try the commands. Are they discoverable? Do they work?' },

    { type: 'quiz', question: 'You create a custom command called `/deploy` that runs production deployment scripts. What is the most important safety measure to add?', options: ['Add a comment saying "use carefully"', 'Add explicit confirmation steps in the command and a warning about the environment being targeted — production deployments should never run automatically without human confirmation', 'Password-protect the command file', 'Only include the command in branches, not main'], correct: 1, explanation: 'High-stakes operations like production deployments need explicit human confirmation steps built into the command. For example: "Before running any deployment command, list the exact commands you will run and ask for explicit confirmation. State clearly whether this is targeting staging or production." The goal is to ensure the human understands what will happen and can stop it. Never design an autonomous AI command to execute irreversible production operations without a checkpoint.' },

    { type: 'quiz', question: 'A custom slash command you wrote works perfectly for Python files but produces poor output for JavaScript files. What is the most likely cause?', options: ['Custom commands cannot work across file types', 'The command\'s instructions use Python-specific language or assumptions that don\'t translate to JavaScript', 'JavaScript files are not supported by Claude Code', 'The command file needs to be in a different directory for JavaScript'], correct: 1, explanation: 'Command prompts often contain implicit assumptions about the language or framework. For example, "check for proper use of Python docstrings" doesn\'t apply to JavaScript. To make a command language-agnostic, use language-neutral language: "check that all public functions are documented" instead of "check for docstrings". Alternatively, create language-specific commands: review-python.md, review-js.md, each with appropriate language-specific checks.' }
  ]
},

'7-8': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Your First Hook', content: 'Hooks are shell commands that run automatically around Claude Code\'s actions. This drill creates your first one.\n\n**Step 1 — Open Claude Code settings:**\n```\n/settings\n```\nOr via the CLI: `claude config`\n\n**Step 2 — Understand the hook events** (ask Claude Code or check docs):\n- `PreToolUse` — runs before Claude Code uses a tool\n- `PostToolUse` — runs after Claude Code uses a tool\n- `Stop` — runs when Claude Code finishes\n\n**Step 3 — Create a simple notification hook** — plays a sound or shows a notification when Claude Code finishes:\n```json\n{\n    "hooks": {\n        "Stop": [\n            {\n                "matcher": "",\n                "hooks": [\n                    {\n                        "type": "command",\n                        "command": "echo \'Claude Code task completed!\' | powershell -command \\"[System.Media.SystemSounds]::Beep.Play()\\""\n                    }\n                ]\n            }\n        ]\n    }\n}\n```\n\n**Step 4 — Test the hook** by running a Claude Code task.\n\n**Step 5 — Adjust the notification** to something useful for your workflow.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Auto-Test Hook', content: 'Build a hook that automatically runs your tests every time Claude Code modifies Python files.\n\n**Step 1 — Identify your test command:**\n```powershell\npython -m pytest tests/  # or whatever runs your tests\n```\n\n**Step 2 — Add a PostToolUse hook** that runs tests after file edits:\n```json\n{\n    "hooks": {\n        "PostToolUse": [\n            {\n                "matcher": "Write|Edit",\n                "hooks": [\n                    {\n                        "type": "command",\n                        "command": "python -m pytest tests/ --tb=short -q",\n                        "timeout": 60\n                    }\n                ]\n            }\n        ]\n    }\n}\n```\n\n**Step 3 — Test the hook:** Ask Claude Code to edit a Python file. Do tests run automatically?\n\n**Step 4 — Review the hook\'s output:** Does Claude Code adjust its behaviour when tests fail?\n\n**Step 5 — Ask Claude:** *"Review this hook configuration. What edge cases might cause it to run at the wrong time or produce confusing output?"*' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Logging Hook for AI Auditability', content: 'Build a hook that logs every tool Claude Code uses — creating an audit trail of AI actions.\n\n**Step 1 — Create a log file:**\n```powershell\nnew-item claude-audit.log\n```\n\n**Step 2 — Add a logging hook** to record all tool usage:\n```json\n{\n    "hooks": {\n        "PreToolUse": [\n            {\n                "matcher": "",\n                "hooks": [\n                    {\n                        "type": "command",\n                        "command": "echo [$(Get-Date -Format \'yyyy-MM-dd HH:mm:ss\')] CLAUDE TOOL: $CLAUDE_TOOL_NAME >> claude-audit.log"\n                    }\n                ]\n            }\n        ]\n    }\n}\n```\n\n**Step 3 — Run a Claude Code session** with a real task. Examine the log file afterwards.\n\n**Step 4 — Add the log file to .gitignore** (it\'s runtime data, not code).\n\n**Step 5 — Ask Claude:** *"Looking at this audit log from my Claude Code session [paste key lines], does the sequence of tool use match what I expected Claude Code to do for the task I gave it? What does it reveal?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Safety Hook for Dangerous Operations', content: 'Build a hook that intercepts dangerous commands and requires confirmation before execution.\n\n**Step 1 — Identify dangerous commands** in your context: `rm -rf`, `DROP TABLE`, `git push --force`, `DELETE FROM`.\n\n**Step 2 — Build a blocking hook** that prompts before dangerous operations:\n```json\n{\n    "hooks": {\n        "PreToolUse": [\n            {\n                "matcher": "Bash",\n                "hooks": [\n                    {\n                        "type": "command",\n                        "command": "if ($env:CLAUDE_TOOL_INPUT -match \'rm -rf|DROP TABLE|--force\') { Write-Host \'⚠️  DANGEROUS COMMAND DETECTED. Claude Code wants to run: \' + $env:CLAUDE_TOOL_INPUT; $confirm = Read-Host \'Allow? (yes/no)\'; if ($confirm -ne \'yes\') { exit 1 } }"\n                    }\n                ]\n            }\n        ]\n    }\n}\n```\n\n**Step 3 — Test the hook** by asking Claude Code to do something that would trigger it.\n\n**Step 4 — Review the hook.** Are there dangerous patterns you haven\'t covered? Are there any false positives (safe commands that would incorrectly trigger it)?\n\n**Step 5 — Ask Claude:** *"Review this safety hook. What dangerous commands does it miss? What safe commands might it incorrectly flag?"*' },

    { type: 'quiz', question: 'You add a PostToolUse hook that runs tests after every file edit. Claude Code edits 10 files in sequence. What is the potential problem?', options: ['The hook will not run after multiple edits', 'Tests run after every single edit, even when the project is in a broken intermediate state — causing many test failures for temporarily incomplete code', 'The hook will slow down Claude Code permanently', 'Tests cannot be run from hooks'], correct: 1, explanation: 'Running tests after every individual edit causes "intermediate state" failures — when implementing a feature that requires changes to multiple files, the project is broken between edits. A smarter approach: run tests only after Claude Code indicates it\'s done with a task, or add a delay. Use the `Stop` hook (runs when the session ends) instead of `PostToolUse`, or add a hook that only runs tests if the preceding edit was the last in a sequence.' },

    { type: 'quiz', question: 'A blocking PreToolUse hook exits with code 1 when a dangerous command is detected. What happens to Claude Code?', options: ['Claude Code ignores the hook and runs the command anyway', 'Claude Code receives the non-zero exit code as feedback and should not proceed with the tool use — the hook effectively blocks the action', 'Claude Code crashes and loses all progress', 'The hook must exit with a specific error code to block — exit 1 is not enough'], correct: 1, explanation: 'When a hook exits with a non-zero exit code, Claude Code treats this as a signal to not proceed with the planned tool use. This is the designed blocking mechanism. The hook\'s stdout/stderr is available to Claude Code as context for why the action was blocked, allowing it to report the blocking reason to you and potentially request permission or adjust its plan.' }
  ]
},

'7-9': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Memory System Exploration', content: 'Understand Claude Code\'s memory system through hands-on exploration.\n\n**Step 1 — Open Claude Code in a project.**\n\n**Step 2 — Ask Claude Code about its memory:**\n"What do you currently know about this project that you\'ll remember in future sessions?"\n\n**Step 3 — Test adding to memory:**\n"Please remember that in this project, we always add a \'last_modified\' timestamp to any database record we create or update."\n\n**Step 4 — Start a new session** (close and reopen Claude Code in the same project).\n\n**Step 5 — Test retention:**\n"What do you remember about conventions for database records in this project?"\nDid it retain the instruction?\n\n**Step 6 — Ask Claude.ai (browser):** *"How does Claude Code\'s memory system work? What persists between sessions and what doesn\'t? What\'s the difference between CLAUDE.md and the memory system?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Populate Memory for a Project', content: 'Systematically populate Claude Code\'s memory with everything it needs to work effectively on your project.\n\n**Step 1 — Open Claude Code in a real project.**\n\n**Step 2 — Add 5-7 memory items** covering critical project knowledge:\n- A decision that isn\'t obvious from the code: "We use token-based auth instead of session-based because [reason]"\n- A convention that matters: "All API endpoints return a standard envelope: {success, data, error}"\n- A constraint to respect: "Never use recursion in the file parser — it caused stack overflow with large files"\n- A testing requirement: "Integration tests require a running database — run `docker-compose up` first"\n- A deployment detail: "The staging server uses a different .env file at /etc/app/.env"\n\n**Step 3 — Test each memory item** by starting a new session and asking questions that require the knowledge.\n\n**Step 4 — Document what you added to memory** in your CLAUDE.md as well, so it\'s not lost if memory is cleared.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Memory vs CLAUDE.md Strategy', content: 'Understand when to use memory vs CLAUDE.md and build a coherent strategy.\n\n**Step 1 — Ask Claude:** *"When should I use Claude Code\'s memory vs CLAUDE.md to store project information? What are the differences in: persistence, visibility to other developers, how it\'s used during sessions, and what each is best for?"*\n\n**Step 2 — Create a decision framework:**\n| Information type | Memory or CLAUDE.md | Reason |\n|---|---|---|\n| Shared team conventions | | |\n| Personal preferences | | |\n| Temporary task notes | | |\n| Architecture decisions | | |\n| One-time debugging context | | |\n\n**Step 3 — Fill in the table** based on Claude\'s explanation.\n\n**Step 4 — Audit your current project:** What information lives in each place? What should be moved?\n\n**Step 5 — Apply your framework** to decide where to store 3 pieces of information from your actual project.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Memory Reset and Recovery Protocol', content: 'Build a protocol for when memory is cleared or becomes stale.\n\n**Step 1 — Simulate a memory reset:** Ask Claude Code to forget or disregard its stored memory about the project.\n\n**Step 2 — Design a recovery prompt** — a single message you can run at the start of any fresh session:\n```\nProject onboarding: Read CLAUDE.md and the following key files: [list]. \nAfter reading, confirm:\n1. What is this project?\n2. What are the most important conventions I should follow?\n3. What should I avoid?\n4. How do I run the tests?\n```\n\n**Step 3 — Test the recovery prompt** after clearing memory. Does it get Claude Code back to a useful state quickly?\n\n**Step 4 — Add the recovery prompt** to CLAUDE.md as a "New Session Startup" section.\n\n**Step 5 — Ask Claude:** *"Is there anything important about this project that can\'t be recovered from CLAUDE.md and source files alone — things that would be permanently lost if memory was cleared?"* If yes, add those things to CLAUDE.md.' },

    { type: 'quiz', question: 'You tell Claude Code "Remember that we\'re migrating from PostgreSQL to MongoDB next month." You start a new Claude Code session a week later. Will it remember this?', options: ['Yes — Claude Code\'s memory persists indefinitely across sessions', 'It depends on how Claude Code\'s memory is configured and whether the session is tied to the same project', 'No — Claude Code never retains anything between sessions', 'Yes — but only for 7 days, then it expires'], correct: 1, explanation: 'Claude Code\'s memory persistence depends on the implementation and configuration. Claude Code can store project-level memory that persists, but this behaviour varies. The safest practice: treat anything important as potentially lost and document it in CLAUDE.md or a persistent file in your project. For critical architectural context like "migrating from X to Y", don\'t rely on memory alone — put it in CLAUDE.md.' },

    { type: 'quiz', question: 'What is the difference between information in CLAUDE.md and information in Claude Code\'s memory system?', options: ['They are identical — CLAUDE.md is just a human-readable version of the memory system', 'CLAUDE.md is a file in your git repository (visible to all, version-controlled, persistent); memory is session-specific storage that may or may not persist across sessions and is not tracked by git', 'Memory is more reliable than CLAUDE.md for important information', 'CLAUDE.md is read before the session; memory is consulted during the session'], correct: 1, explanation: 'CLAUDE.md is a committed file — it\'s in git history, visible to all collaborators, survives any Claude Code reinstall, and is the primary source of truth for project context. Memory is AI-managed storage that is more ephemeral and may not persist across machines or after updates. For anything that must reliably be known in every session, CLAUDE.md is the authoritative source.' }
  ]
},

'7-10': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Plan Mode Drill', content: 'This drill practices using Plan Mode to review Claude Code\'s approach before it executes.\n\n**Step 1 — Start Claude Code with Plan Mode:**\n```powershell\nclaude --plan-mode\n```\nOr in a session, ask Claude Code to "describe your plan before taking any action."\n\n**Step 2 — Give a complex task** that will require multiple steps:\n"Add user authentication to this Flask application. It should support registration, login, and password reset via email."\n\n**Step 3 — Read the plan carefully.** Ask yourself:\n- Does the sequence of steps make sense?\n- Are there steps that will change things I don\'t want changed?\n- Are there important steps missing?\n- What risks does the plan create?\n\n**Step 4 — Provide feedback on the plan** before approving:\n"Before implementing, I want to change step 3 — use JWT instead of session cookies. Also add a step to update the tests before the implementation."\n\n**Step 5 — Approve the modified plan** and watch Claude Code execute it.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Permissions Configuration for Real Work', content: 'Configure Claude Code\'s permissions appropriately for your specific work context.\n\n**Step 1 — Understand the permission levels** (ask Claude Code: "Explain each permission level and what it allows").\n\n**Step 2 — Assess your risk tolerance:**\n- High-trust environment (personal project, throwaway code): more autonomy\n- Medium-trust (team project, staging): moderate autonomy with file write confirmation\n- Low-trust (production systems, sensitive data): minimal autonomy, confirm everything\n\n**Step 3 — Configure permissions** for your most common use case. Check the Claude Code documentation or settings for current permission configuration options.\n\n**Step 4 — Test your configuration:** Ask Claude Code to do something that would previously have run automatically. Does it now ask for confirmation?\n\n**Step 5 — Document your permission strategy** in CLAUDE.md: "When working in this project, always operate in [mode] — we require confirmation before [types of operations]."' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — When to Use Plan Mode vs Direct Execution', content: 'Build judgment about when to require a plan vs when to let Claude Code work directly.\n\n**Step 1 — Ask Claude:** *"Describe 5 situations where Plan Mode is essential before letting Claude Code execute, and 5 situations where going directly to execution is fine and Plan Mode would just add unnecessary friction."*\n\n**Step 2 — Create your personal decision rule:**\n\nRequire Plan Mode when:\n- [ ] (your criteria)\n- [ ] (your criteria)\n\nDirect execution is fine when:\n- [ ] (your criteria)\n- [ ] (your criteria)\n\n**Step 3 — Apply the rule** to 3 recent Claude Code tasks you\'ve done. Would Plan Mode have been appropriate for any?\n\n**Step 4 — Ask Claude:** *"Given that I work on [describe your project and its criticality], what is the right balance between planning and execution for my specific context?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build a Permissions Policy Document', content: 'Create a formal policy for Claude Code usage on your project — what it can do autonomously and what requires human approval.\n\n**Step 1 — Ask Claude to help you design the policy:**\n```\nHelp me write a Claude Code permissions policy for a [type of project]. The policy should specify:\n1. Operations Claude Code can do automatically (no confirmation needed)\n2. Operations requiring my explicit approval before execution\n3. Operations that are completely off-limits for Claude Code\n4. Situations requiring Plan Mode review before any action\n```\n\n**Step 2 — Review and adapt the policy** for your specific project risk level.\n\n**Step 3 — Add the policy to CLAUDE.md** in a "Permissions and Autonomy" section.\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review this permissions policy. What gaps exist? What dangerous operations are implicitly allowed that should be explicitly restricted?"*\n\n**Step 5 — Share with your team** if you have collaborators.' },

    { type: 'quiz', question: 'You use Plan Mode and Claude Code\'s plan says "Step 4: Delete the old authentication module." You don\'t want to delete it — you want to keep it for rollback purposes. What do you do?', options: ['Accept the plan and manually undo step 4 after it runs', 'In the plan review, tell Claude Code to change step 4 from "delete" to "move to archive/ directory" before approving the plan', 'Accept the plan — you can always recover from git', 'Reject the entire plan and start over'], correct: 1, explanation: 'Plan Mode exists specifically for this scenario: you can modify the plan before execution. Tell Claude Code precisely what to change: "Change step 4 — instead of deleting the old module, move it to archive/auth-old.py. This preserves it for rollback." This is far better than accepting the plan and hoping to recover from git, which is possible but adds unnecessary risk and recovery effort.' },

    { type: 'quiz', question: 'Claude Code runs in default permission mode. It attempts to run `pip install flask` to add a dependency. Should this require confirmation?', options: ['No — installing dependencies is a routine task', 'Yes — Claude Code should always confirm before installing packages, as they can introduce security vulnerabilities or version conflicts', 'Only if the project has a virtual environment', 'Depends on whether the package is well-known'], correct: 1, explanation: 'Package installation has genuine risks: packages can contain malicious code, introduce version conflicts, and in some environments require elevated privileges. Even well-known packages should be confirmed — you want to review what\'s being installed and why. For automated environments like CI, pre-approved packages are fine, but for interactive development sessions, confirming package installations is a reasonable safety gate.' }
  ]
},

'7-11': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Sub-Agent Concept Exploration', content: 'Understand sub-agents concretely before using them.\n\n**Step 1 — Ask Claude Code:** "Explain what sub-agents are in Claude Code. How do they differ from a single-agent session? When does spawning a sub-agent make sense vs doing the work in the main session?"\n\n**Step 2 — Ask for concrete examples:** "Give me 3 concrete examples of tasks where spawning a sub-agent would complete the work faster or better than having the main agent do it alone."\n\n**Step 3 — Ask about the risks:** "What can go wrong when Claude Code uses sub-agents? What should I watch for when reviewing the work of a sub-agent session?"\n\n**Step 4 — Ask about context:** "When a sub-agent is spawned, what context does it have? Does it read CLAUDE.md? Does it know what the main agent is working on?"\n\n**Step 5 — Summarise your understanding** in 3 bullet points: what sub-agents are, when to use them, and what to watch out for.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Parallel Work with Sub-Agents', content: 'Use sub-agents to complete parallel independent tasks simultaneously.\n\n**Step 1 — Identify a task that can be split into 2-3 independent parts.** For example:\n- Writing tests for 3 separate modules simultaneously\n- Generating documentation for 3 different components\n- Adding error handling to 3 independent utility files\n\n**Step 2 — Ask Claude Code to execute the task using parallel sub-agents:**\n```\nI need to add comprehensive error handling to these 3 files: utils.py, api.py, and database.py. These are independent — they don\'t call each other. Please use parallel sub-agents to work on all 3 simultaneously to finish faster.\n```\n\n**Step 3 — Monitor the parallel execution.** Does Claude Code actually parallelize?\n\n**Step 4 — Review each sub-agent\'s output** individually before accepting.\n\n**Step 5 — Ask Claude:** "Did parallelizing this task produce any inconsistencies between the files? Are all 3 using the same error handling patterns?"' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Design a Sub-Agent Architecture', content: 'Design a complex workflow that uses sub-agents effectively.\n\n**Step 1 — Choose a complex task** from your work that has multiple independent components.\n\n**Step 2 — Ask Claude.ai (browser):**\n```\nI have this complex task to complete with Claude Code: [describe your task]\n\nDesign a sub-agent architecture for this:\n1. Identify which parts can run in parallel (independent sub-agents)\n2. Identify which parts must run sequentially (dependencies)\n3. Define what each sub-agent\'s specific task would be\n4. Describe how results from sub-agents get integrated\n5. Identify the risks in this multi-agent approach\n```\n\n**Step 3 — Review the architecture.** Does the parallelization make sense? Are the dependencies correct?\n\n**Step 4 — Estimate the time savings:** If done sequentially, how long would it take? With parallel sub-agents?\n\n**Step 5 — Decide:** Is the complexity of multi-agent coordination worth the time savings for this task?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Sub-Agent Results Integration', content: 'Practice the critical step of integrating and reviewing multiple sub-agent outputs.\n\n**Step 1 — Run a parallel sub-agent task** from Workshop B (or a similar one).\n\n**Step 2 — After all sub-agents complete**, before accepting anything, run an integration review:\n```\nYou\'ve completed work across 3 files using parallel agents. Before I accept any changes:\n1. Are there any inconsistencies between the approaches taken in each file?\n2. Do the changes in each file work correctly when used together?\n3. Is there any code that was duplicated that should be shared?\n4. Are there any naming conventions that don\'t match between files?\n```\n\n**Step 3 — Ask Claude Code to resolve any inconsistencies** it identifies.\n\n**Step 4 — Run the full test suite** to verify everything works together.\n\n**Step 5 — Commit the changes** with a message documenting that parallel sub-agents were used.' },

    { type: 'quiz', question: 'You ask Claude Code to use parallel sub-agents to refactor your entire codebase simultaneously. What is the most significant risk?', options: ['Sub-agents are slower than a single agent', 'Parallel agents working independently may make incompatible changes — for example, both agents refactoring the same shared utility function differently', 'Sub-agents cannot read your CLAUDE.md', 'The cost of parallel agents is higher than sequential work'], correct: 1, explanation: 'The main risk of parallel agents is coordination failures — when two agents independently modify code that interacts, they can make incompatible changes. For example, Agent A renames a function; Agent B adds new calls to the old name. The solution: ensure tasks are truly independent (different files that don\'t interact), or use a sequenced approach where the main agent reviews intermediate results before spawning the next batch.' },

    { type: 'quiz', question: 'A sub-agent completes a task and returns results to the main agent. Without reviewing the sub-agent\'s work, the main agent incorporates the results. What could go wrong?', options: ['The main agent will automatically catch and fix any errors', 'Sub-agents can make mistakes that the main agent accepts without verification — the main agent may not re-read and validate what the sub-agent produced', 'Sub-agents always produce verified results', 'The main agent will refuse to use unreviewed sub-agent output'], correct: 1, explanation: 'Sub-agents can produce incorrect or incomplete results. The main agent incorporating sub-agent output without independent verification propagates any errors silently. Best practice: ask the main agent to explicitly verify sub-agent results before incorporating them: "Review what the sub-agents produced before using their output." For critical changes, apply your own review before accepting.' }
  ]
},

'7-12': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop A — Settings Exploration', content: 'Explore Claude Code\'s configuration options systematically.\n\n**Step 1 — View all settings:**\n```powershell\nclaude config\n```\nor ask Claude Code: "List all your configuration settings and their current values."\n\n**Step 2 — Explore each setting category:**\n- Model selection\n- Context window size\n- Permission mode\n- Output format\n- Hooks\n\n**Step 3 — Ask Claude Code:** "What are the 5 most impactful settings for a developer who primarily does [your work type]? What should each be set to and why?"\n\n**Step 4 — Change one setting** and test the difference.\n\n**Step 5 — Ask Claude Code:** "What settings would you recommend I NOT change from their defaults? What defaults exist for important reasons?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Optimise Claude Code for Your Workflow', content: 'Tune Claude Code settings to maximise value for your specific work.\n\n**Step 1 — Describe your workflow** to Claude.ai:\n```\nI use Claude Code for these tasks primarily: [list your top 3-4 uses].\nMy project type is: [language, framework, complexity].\nMy team size is: [solo / small / large].\nMy risk tolerance is: [high = personal project / low = production system].\n\nRecommend specific Claude Code settings for my situation. For each setting, tell me what to change it to and why.\n```\n\n**Step 2 — Apply the recommended settings.**\n\n**Step 3 — Run a typical work session** with the new settings. Do they feel better?\n\n**Step 4 — Mandatory settings review:** Ask Claude: *"Are there any settings you recommended that could cause unexpected problems? What\'s the worst-case scenario of each setting you changed?"*\n\n**Step 5 — Document your settings** in a `~/.claude-settings-notes.md` file for future reference.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Cost Optimisation', content: 'Claude Code API usage costs money. This workshop optimises your usage without sacrificing quality.\n\n**Step 1 — Understand Claude Code cost drivers:**\n- Tokens sent (input): every file it reads costs tokens\n- Tokens received (output): every response costs tokens\n- Model choice: Opus costs ~5x more than Sonnet; Haiku costs ~20x less\n\n**Step 2 — Ask Claude:** *"What strategies would reduce my Claude Code API costs without significantly reducing quality? For each strategy, estimate the cost reduction and quality impact."*\n\n**Step 3 — Identify your high-cost patterns:** When does Claude Code read many large files unnecessarily? When does it produce very long responses when shorter ones would do?\n\n**Step 4 — Apply cost-reduction strategies:**\n- Use Haiku model for simple tasks (file renaming, basic formatting)\n- Use Sonnet for most development tasks\n- Reserve Opus for complex architectural decisions\n- Use concise CLAUDE.md (not exhaustive — every line adds to context)\n\n**Step 5 — Estimate your monthly cost** based on typical usage. Is it justified by productivity gains?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Complete Claude Code Setup Review', content: 'Perform a comprehensive review of your entire Claude Code setup and produce a "best of" configuration.\n\n**Step 1 — Inventory your current setup:**\n- CLAUDE.md: what\'s in it?\n- Custom commands: which ones do you have?\n- Hooks: which hooks are configured?\n- Memory: what has been stored?\n- Settings: what\'s configured?\n\n**Step 2 — Ask Claude to audit your setup:**\n```\nHere is my complete Claude Code setup: [describe everything in step 1]\n\nPerform a comprehensive audit:\n1. What is working well?\n2. What is missing that would significantly improve my workflow?\n3. What is redundant or unnecessary?\n4. What configuration conflict or problem might I not have noticed?\n5. What would you change first if you were setting this up fresh?\n```\n\n**Step 3 — Apply the top 3 improvements** from the audit.\n\n**Step 4 — Export your configuration** to a backup location (cloud storage, separate repo).\n\n**Step 5 — Set a calendar reminder** to review and update your Claude Code setup in 60 days.' },

    { type: 'quiz', question: 'You notice Claude Code is reading all 50 files in your project before answering even simple questions. This is causing slow responses and high costs. How should you address this?', options: ['Accept it — Claude Code needs full context to be reliable', 'Improve CLAUDE.md to tell Claude Code which files are important for which types of tasks, and use @file references to guide it to specific files instead of reading everything', 'Use a smaller model that reads fewer files', 'Reduce the number of files in your project'], correct: 1, explanation: 'Claude Code\'s context efficiency is heavily influenced by how you guide it. Add to CLAUDE.md: "For authentication questions, read auth.py. For database questions, read models.py. Only read other files if those don\'t contain the answer." Also, in your requests, use specific references: "Looking at auth.py only, what does the login function do?" This reduces unnecessary file reading while maintaining accuracy where it matters.' },

    { type: 'quiz', question: 'You want to use Claude Haiku for quick tasks and Claude Sonnet for complex ones in your Claude Code workflow. How do you implement this?', options: ['Claude Code automatically chooses the right model', 'Set Claude Sonnet as your default model and specify Haiku in your prompt for simple tasks: "using the fastest available model, rename these files"', 'You cannot use multiple models in the same Claude Code installation', 'Create two separate Claude Code installations with different model configs'], correct: 1, explanation: 'You can configure Claude Code\'s default model and override it per-session or per-request. Set Sonnet as your default (good quality/cost balance). For tasks where speed matters more than deep reasoning (renaming, formatting, generating boilerplate), you can specify a lighter model in your instruction. Some tasks genuinely need Opus\'s deeper reasoning (complex architecture decisions, difficult debugging); most routine coding tasks are well-served by Sonnet.' }
  ]
}

};

function enhance(id, filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const lesson = JSON.parse(raw);
  const enh = enhancements[id];
  if (!enh) { console.log('SKIP '+id); return; }
  let successIdx = -1;
  for (let i = lesson.sections.length - 1; i >= 0; i--) {
    if (lesson.sections[i].type === 'callout' && lesson.sections[i].variant === 'success') {
      successIdx = i; break;
    }
  }
  const insertAt = successIdx >= 0 ? successIdx : lesson.sections.length;
  lesson.sections.splice(insertAt, 0, ...enh.sections);
  lesson.estimatedMinutes += enh.addMinutes;
  fs.writeFileSync(filePath, JSON.stringify(lesson, null, 2));
  const ws = lesson.sections.filter(s=>s.type==='workshop').length;
  const qz = lesson.sections.filter(s=>s.type==='quiz').length;
  console.log('OK '+id+' | ws:'+ws+' qz:'+qz+' mins:'+lesson.estimatedMinutes);
}

